import asyncio
import os
import shlex
import sqlite3
import subprocess
import sys
from pathlib import Path


def environ() -> None:
    os.system("echo " + os.environ["NAME"])


def getenv() -> None:
    os.popen(os.getenv("CMD", "true"))


def shell() -> None:
    subprocess.run(f"grep {input()} log.txt", shell=True)


def argv() -> None:
    subprocess.run(["grep", input(), "log.txt"])


def no_shell() -> None:
    subprocess.run("ls " + sys.argv[1], shell=False)


def not_the_command() -> None:
    subprocess.run("ls", cwd=input(), shell=True)


async def literal_shell() -> None:
    await asyncio.create_subprocess_exec("sh", "-c", input())


async def program_argument() -> None:
    await asyncio.create_subprocess_exec("grep", input(), "log.txt")


def quoted() -> None:
    os.system("ls " + shlex.quote(sys.argv[1]))


def evaluated() -> None:
    eval(sys.stdin.read())


def path() -> str:
    return (Path(os.environ["HOME"]) / ".config").read_text()


def compound(connection: sqlite3.Connection) -> None:
    query = "SELECT * FROM users WHERE "
    query += sys.argv[1]
    connection.execute(query)


def parameterized(cursor: sqlite3.Cursor) -> None:
    cursor.execute("SELECT * FROM users WHERE name = ?", (input(),))


def number() -> None:
    os.system("sleep " + str(int(input())))


def overwritten() -> None:
    name = input()
    name = "guest"
    os.system("echo " + name)


def only_decides() -> None:
    if os.getenv("DEBUG"):
        os.system("echo debug")


def lines() -> None:
    for line in sys.stdin:
        os.system(line)


def write(path: str) -> None:
    open(path, "w").close()


def via_sink() -> None:
    write(input())


def ignores(path: str) -> str:
    return "settings.toml"


def via_ignoring() -> None:
    open(ignores(input()))


def target() -> str:
    return os.environ["TARGET"]


def via_source() -> None:
    os.system(target())


def environment() -> None:
    subprocess.run(["env"], env=os.environ)


class Settings:
    def __init__(self) -> None:
        self.path = os.environ["SETTINGS"]


def fields(settings: Settings) -> None:
    open(settings.path)


def listed_program() -> None:
    subprocess.run([os.environ["EDITOR"], "notes.txt"])


def listed_code() -> None:
    subprocess.check_output(["bash", "-c", input()])


def listed_data() -> None:
    subprocess.run(["sh", "-c", "echo $0", input()])


def string_program() -> None:
    subprocess.call(os.environ["EDITOR"])


def keyword_list() -> None:
    subprocess.Popen(args=[sys.argv[1], "--version"])


def variable_list() -> None:
    command = [input(), "--version"]
    subprocess.run(command)


def exec_code() -> None:
    os.execl("/bin/sh", "sh", "-c", input())


def exec_listed_code() -> None:
    os.execv("/bin/sh", ["sh", "-c", input()])


def exec_data() -> None:
    os.execv("/usr/bin/grep", ["grep", input()])
